import{_ as a,c as i,o as t,ag as e}from"./chunks/framework.D4Vqf8I7.js";const r=JSON.parse('{"title":"Руководство по управлению корневыми сертификатами в ОС Альт (ALT Linux)","description":"","frontmatter":{},"headers":[],"relativePath":"docs/wi/cert.md","filePath":"docs/wi/cert.md","lastUpdated":1786699528000}'),h={name:"docs/wi/cert.md"};function l(p,s,n,d,c,k){return t(),i("div",null,s[0]||(s[0]=[e('<h1 id="руководство-по-управлению-корневыми-сертификатами-в-ос-альт-alt-linux" tabindex="-1">Руководство по управлению корневыми сертификатами в ОС Альт (ALT Linux) <a class="header-anchor" href="#руководство-по-управлению-корневыми-сертификатами-в-ос-альт-alt-linux" aria-label="Permalink to &quot;Руководство по управлению корневыми сертификатами в ОС Альт (ALT Linux)&quot;">​</a></h1><h2 id="_1-система-управления-сертификатами" tabindex="-1">1. Система управления сертификатами <a class="header-anchor" href="#_1-система-управления-сертификатами" aria-label="Permalink to &quot;1. Система управления сертификатами&quot;">​</a></h2><p>В ОС Альт управление доверенными корневыми сертификатами осуществляется с помощью пакета <code>ca-trust</code>, который включает утилиту <code>update-ca-trust</code>.</p><p>Для проверки наличия пакетов в репозитории используется команда (выполняется без привилегий):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ca-trust</span></span></code></pre></div><p>Ожидаемый вывод содержит строки:</p><ul><li><code>ca-trust</code> – основной пакет инфраструктуры доверия;</li><li><code>ca-trust-directory-hash</code> – хук для создания каталога с хеш‑ссылками;</li><li><code>ca-trust-java</code> – хук для интеграции с Java.</li></ul><p>Установка пакета (при необходимости) выполняется от имени суперпользователя:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ca-trust</span></span></code></pre></div><p>Система сертификатов в ОС Альт соответствует модели Red Hat Enterprise Linux (RHEL) и использует каталоги <code>/etc/pki/ca-trust/</code> и <code>/etc/pki/tls/certs/</code>.</p><h2 id="_2-расположение-системных-фаилов-сертификатов" tabindex="-1">2. Расположение системных файлов сертификатов <a class="header-anchor" href="#_2-расположение-системных-фаилов-сертификатов" aria-label="Permalink to &quot;2. Расположение системных файлов сертификатов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Назначение</th><th>Путь</th></tr></thead><tbody><tr><td>Каталог для размещения пользовательских корневых сертификатов</td><td><code>/etc/pki/ca-trust/source/anchors/</code></td></tr><tr><td>Альтернативный каталог для корневых сертификатов</td><td><code>/usr/share/pki/ca-trust-source/anchors/</code></td></tr><tr><td>Основной файл со всеми доверенными сертификатами (в формате PEM)</td><td><code>/etc/pki/tls/certs/ca-bundle.crt</code></td></tr><tr><td>Файл сертификатов с атрибутами доверия</td><td><code>/etc/pki/tls/certs/ca-bundle.trust.crt</code></td></tr><tr><td>Извлечённые сертификаты для OpenSSL</td><td><code>/etc/pki/ca-trust/extracted/pem/</code></td></tr></tbody></table><p>Все команды модификации файлов в указанных каталогах требуют прав суперпользователя.</p><h2 id="_3-добавление-пользовательских-корневых-сертификатов" tabindex="-1">3. Добавление пользовательских корневых сертификатов <a class="header-anchor" href="#_3-добавление-пользовательских-корневых-сертификатов" aria-label="Permalink to &quot;3. Добавление пользовательских корневых сертификатов&quot;">​</a></h2><p>Для добавления собственного корневого сертификата в системное хранилище необходимо выполнить следующие действия (все команды выполняются от root):</p><ol><li>Поместить файл сертификата в формате PEM (с расширением <code>.crt</code>) в каталог:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_cert.crt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/ca-trust/source/anchors/</span></span></code></pre></div><ol start="2"><li>Обновить системное хранилище сертификатов:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update-ca-trust</span></span></code></pre></div><p>или</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update-ca-trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract</span></span></code></pre></div><p>После выполнения этих команд все сертификаты из каталога <code>anchors/</code> будут объединены в файлы <code>ca-bundle.crt</code> и <code>ca-bundle.trust.crt</code>.</p><h2 id="_4-просмотр-установленных-сертификатов" tabindex="-1">4. Просмотр установленных сертификатов <a class="header-anchor" href="#_4-просмотр-установленных-сертификатов" aria-label="Permalink to &quot;4. Просмотр установленных сертификатов&quot;">​</a></h2><h3 id="_4-1-просмотр-с-помощью-утилиты-trust-рекомендованныи-способ" tabindex="-1">4.1. Просмотр с помощью утилиты <code>trust</code> (рекомендованный способ) <a class="header-anchor" href="#_4-1-просмотр-с-помощью-утилиты-trust-рекомендованныи-способ" aria-label="Permalink to &quot;4.1. Просмотр с помощью утилиты `trust` (рекомендованный способ)&quot;">​</a></h3><p>Для просмотра списка всех доверенных сертификатов:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Для получения подробной информации по каждому сертификату:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detail</span></span></code></pre></div><h3 id="_4-2-просмотр-содержимого-фаила-ca-bundle-crt" tabindex="-1">4.2. Просмотр содержимого файла <code>ca-bundle.crt</code> <a class="header-anchor" href="#_4-2-просмотр-содержимого-фаила-ca-bundle-crt" aria-label="Permalink to &quot;4.2. Просмотр содержимого файла `ca-bundle.crt`&quot;">​</a></h3><p>Просмотр всего файла (очень большой объём вывода):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/tls/certs/ca-bundle.crt</span></span></code></pre></div><p>Подсчёт количества сертификатов в хранилище:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;BEGIN CERTIFICATE&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/tls/certs/ca-bundle.crt</span></span></code></pre></div><h3 id="_4-3-просмотр-с-помощью-openssl" tabindex="-1">4.3. Просмотр с помощью OpenSSL <a class="header-anchor" href="#_4-3-просмотр-с-помощью-openssl" aria-label="Permalink to &quot;4.3. Просмотр с помощью OpenSSL&quot;">​</a></h3><p>Вывод информации о первом сертификате в файле (команда обрабатывает только один сертификат):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/tls/certs/ca-bundle.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -subject</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -issuer</span></span></code></pre></div><p>Для просмотра всех сертификатов с полной информацией используйте конвейер:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crl2pkcs7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nocrl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -certfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/tls/certs/ca-bundle.crt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkcs7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -print_certs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -text</span></span></code></pre></div><p>Для вывода только полей <code>subject</code> и <code>issuer</code> для всех сертификатов:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crl2pkcs7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nocrl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -certfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/tls/certs/ca-bundle.crt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkcs7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -print_certs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;subject:|issuer:&quot;</span></span></code></pre></div><h2 id="_5-просмотр-сертификатов-в-специализированных-хранилищах" tabindex="-1">5. Просмотр сертификатов в специализированных хранилищах <a class="header-anchor" href="#_5-просмотр-сертификатов-в-специализированных-хранилищах" aria-label="Permalink to &quot;5. Просмотр сертификатов в специализированных хранилищах&quot;">​</a></h2><h3 id="_5-1-хранилище-nss-для-браузеров-firefox-chromium" tabindex="-1">5.1. Хранилище NSS (для браузеров Firefox, Chromium) <a class="header-anchor" href="#_5-1-хранилище-nss-для-браузеров-firefox-chromium" aria-label="Permalink to &quot;5.1. Хранилище NSS (для браузеров Firefox, Chromium)&quot;">​</a></h3><p>Для работы с хранилищем NSS необходимо установить пакет <code>nss-tools</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nss-tools</span></span></code></pre></div><p>Просмотр сертификатов в пользовательском хранилище NSS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certutil</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.pki/nssdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span></span></code></pre></div><p>Если хранилище не инициализировано, команда может вернуть ошибку.</p><h3 id="_5-2-хранилище-java" tabindex="-1">5.2. Хранилище Java <a class="header-anchor" href="#_5-2-хранилище-java" aria-label="Permalink to &quot;5.2. Хранилище Java&quot;">​</a></h3><p>Для просмотра системного хранилища Java <code>cacerts</code> используется утилита <code>keytool</code>. Рекомендуется использовать опцию <code>-cacerts</code>, которая автоматически указывает на системное хранилище:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cacerts</span></span></code></pre></div><p>При запросе пароля введите <code>changeit</code> (стандартный пароль для <code>cacerts</code>, если он не был изменён администратором). Также можно указать пароль непосредственно в команде (небезопасно, так как пароль будет виден в истории команд):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keystore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/java/cacerts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -storepass</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeit</span></span></code></pre></div><p>Для просмотра хранилища, отличного от системного, укажите путь к файлу <code>cacerts</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keytool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keystore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/cacerts</span></span></code></pre></div><h2 id="_6-удаление-сертификатов" tabindex="-1">6. Удаление сертификатов <a class="header-anchor" href="#_6-удаление-сертификатов" aria-label="Permalink to &quot;6. Удаление сертификатов&quot;">​</a></h2><p>Для удаления ранее добавленного сертификата необходимо (от root):</p><ol><li>Удалить соответствующий файл из каталога <code>/etc/pki/ca-trust/source/anchors/</code>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/pki/ca-trust/source/anchors/my_cert.crt</span></span></code></pre></div><ol start="2"><li>Обновить системное хранилище:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update-ca-trust</span></span></code></pre></div><h2 id="_7-примечания" tabindex="-1">7. Примечания <a class="header-anchor" href="#_7-примечания" aria-label="Permalink to &quot;7. Примечания&quot;">​</a></h2><ul><li>Для корректной работы сертификатов они должны быть в формате PEM (X.509) с начальной строкой <code>-----BEGIN CERTIFICATE-----</code>.</li><li>В ОС Альт присутствует собственный корневой центр сертификации: <code>ALT Root Certification</code>.</li><li>В некоторых конфигурациях может присутствовать символическая ссылка <code>/etc/ssl/certs/ca-certificates.crt</code> на <code>/etc/pki/tls/certs/ca-bundle.trust.crt</code>.</li><li>Для работы с российскими сертификатами может потребоваться установка пакета <code>ca-certificates</code>, содержащего сертификаты общедоступных центров сертификации.</li><li>Все команды, изменяющие системные файлы, требуют прав суперпользователя. Для переключения в режим root используйте <code>su -</code> (если известен пароль) или <code>sudo</code>, если он настроен. В руководстве команды, требующие прав root, помечены символом <code>#</code>, команды, выполняемые от имени обычного пользователя, – символом <code>$</code>.</li></ul>',62)]))}const F=a(h,[["render",l]]);export{r as __pageData,F as default};
